from pathlib import Path
import zipfile,hashlib,json,shutil
B=Path(__file__).parent;D=B.parent/'NAR_P8B_DELIVERY_20261124';D.mkdir(exist_ok=True)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def archive(name,files,compression):
 p=D/name; lines=[]
 with zipfile.ZipFile(p,'w',compression=compression,compresslevel=5 if compression==zipfile.ZIP_DEFLATED else None) as z:
  for f,arc in files:
   z.write(f,arc);lines.append(f'{sha(f)}  {arc}')
  z.writestr('SHA256SUMS','\n'.join(lines)+'\n')
 with zipfile.ZipFile(p) as z:
  for line in z.read('SHA256SUMS').decode().splitlines():
   h,n=line.split('  ',1);assert hashlib.sha256(z.read(n)).hexdigest()==h
 return {'name':p.name,'bytes':p.stat().st_size,'sha256':sha(p),'files':len(lines)}
details=[]
for y in range(2017,2024):
 fs=[B/f'b1_{y}_t4.parquet',B/f'b234_{y}_t4.parquet',B/f'pred_{"val" if y>=2022 else "dev"}_{y}_t4.parquet']
 if y<=2021:fs.append(B/f'pred_combine_dev_{y}_t4.parquet')
 details.append(archive(f'NAR_P8B_FREEZE_{y}.zip',[(f,f.name) for f in fs],zipfile.ZIP_STORED))
for y in [2024,2025]:
 fs=[B/'confirm_a'/f'{n}_{y}_t4.parquet' for n in ['features','a34_features','pred_a34val']]+[B/'confirm_b'/f'{n}_{y}_t4.parquet' for n in ['b1','pred_confirm']]
 details.append(archive(f'NAR_P8B_CONFIRM_{y}.zip',[(f,str(f.relative_to(B))) for f in fs],zipfile.ZIP_STORED))
# reference histories are derived, not source canonical.
fs=[B/f for f in ['base.parquet','corner_history_t4.parquet','going_history_t4.parquet']]+[B/'confirm_a'/'enriched_t4.parquet']
details.append(archive('NAR_P8B_REFERENCE.zip',[(f,str(f.relative_to(B))) for f in fs],zipfile.ZIP_STORED))
# Compact code/metrics/guards, excludes raw and binary predictions.
fs=[]
for sub in [B,B/'confirm_a',B/'confirm_b']:
 for f in sorted(sub.iterdir()):
  if f.is_file() and f.suffix in ('.py','.json','.csv','.md','.log'):
   fs.append((f,str(f.relative_to(B))))
compact=archive('NAR_P8B_EVIDENCE_20261124.zip',fs,zipfile.ZIP_DEFLATED)
for n in ['NAR_P8B_REPORT_20261124.md','P9_HANDOFF.md','candidate_config.json','decision_ledger.csv']:
 shutil.copyfile(B/n,D/n)
shutil.copyfile(B/'confirm_b'/'confirmation_result.json',D/'confirmation_result.json')
(D/'delivery_manifest.json').write_text(json.dumps({'status':'LOCAL_VERIFIED','details':details,'compact':compact,'candidate_config_sha256':sha(B/'candidate_config.json'),'selected_for_p9':'P8-Astar-r1','note':'Only t4 detailed freezes included, t1 duplicate checked. No raw input binaries or evaluator labels in bundle.'},ensure_ascii=False,indent=2)+'\n')
(D/'SHA256SUMS').write_text('\n'.join(f'{sha(f)}  {f.name}' for f in sorted(D.iterdir()) if f.is_file() and f.name!='SHA256SUMS')+'\n')
print('archives',len(details),sum(x['bytes'] for x in details),compact,flush=True)

