"""P8B score-only stage. Does not load canonical, historical observations, or labels."""
import duckdb,sys,json,hashlib,itertools
from pathlib import Path
B=Path(__file__).parent; mode=sys.argv[1];th=int(sys.argv[2]); c=duckdb.connect();c.execute(f'set threads={th}');c.execute("set memory_limit='2400MB'");c.execute("set preserve_insertion_order=false")
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
cfg=json.loads((B/'run_config.json').read_text()); m=json.loads((B/'feature_manifest.json').read_text());assert m['status']=='PASS' and m['config_sha256']==sha(B/'run_config.json')
expr={}; support={};families={}
def add(n,f,e,cond):
 expr[n]=f'case when {cond} then {e} else 0.0 end';support[n]=cond;families[n]=f
def clip(x):return f'greatest(-1.,least(1.,{x}))'
for d,w,k,wt in itertools.product(cfg['b1']['dimensions'],cfg['b1']['windows'],cfg['b1']['k'],cfg['b1']['weights']):
 n=f'b1_{d}{w}_k{k}_w{int(wt*100)}';count=f'n_{d}{w}';diff=f'd_{d}{w}'
 add(n,'B1',f'{wt}*{count}/({count}+{k}.0)*{clip(diff)}',f'n_hl60>=2 and n{w}>=2 and {count}>0 and {diff} is not null')
for wt in cfg['b2']['weights']:
 add(f'b2_going_w{int(wt*100)}','B2',f'{wt}*{clip("gdelta")}','n_hl60>=2 and gn>=2 and gdelta is not null')
for dim in ('drawhorse','drawgate'):
 for wt in cfg['b3']['weights']:
  add(f'b3_{dim}_w{int(wt*100)}','B3',f'{wt}*n_{dim}/(n_{dim}+100.)*{clip("d_"+dim)}',f'nr_course>=200 and n_{dim}>0 and d_{dim} is not null')
for dim in ('style3','style5','pressure3','pressure5'):
 for wt in cfg['b4']['weights']:
  add(f'b4_{dim}_w{int(wt*100)}','B4',f'{wt}*n_{dim}/(n_{dim}+100.)*{clip("d_"+dim)}',f'nr_{dim}>=100 and n_{dim}>0 and d_{dim} is not null')
if mode=='dev':models=list(expr); years=range(2017,2022)
elif mode=='val':
 select=json.loads((B/'shortlist.json').read_text());models=select['models']; years=range(2022,2024)
elif mode=='combine_dev':
 select=json.loads((B/'shortlist.json').read_text());models=select['models'];years=range(2017,2022)
else:raise ValueError(mode)
if mode!='dev' and len(models)>1:
 expr['combined']='+'.join(f'({expr[n]})' for n in models);support['combined']=' or '.join(f'({support[n]})' for n in models);families['combined']='B5';models=models+['combined']
# candidate definitions are written for audit, not used for outcome selection by score stage
(B/f'candidate_definitions_{mode}.json').write_text(json.dumps({'models':models,'expressions':{k:expr[k] for k in models},'family':{k:families[k] for k in models}},indent=2)+'\n')
assert c.execute('select list(horse_no order by round(score,12) desc,horse_no) from (values (3,0.12345678901249::double),(1,0.12345678901249::double),(2,0.12345678901251::double)) t(horse_no,score)').fetchone()[0]==[2,1,3]
for y in years:
 files=[B/f'b1_{y}_t{th}.parquet',B/f'b234_{y}_t{th}.parquet',B/'base.parquet']
 for f,n in zip(files,('f','g','b')):
  assert sha(f)==m['files'][f.name];c.execute(f"create or replace view {n} as select * from read_parquet('{f}')"+(f' where year(race_date)={y}' if n=='b' else ''))
  assert [x[0] for x in c.execute('describe '+n).fetchall()]==m['schemas'][n]
 # include all roster rows; no score if base unknown. Additive deltas don't change coverage.
 cols=','.join(f'case when astar is not null then astar+({expr[n]}) end s_{n},case when astar is not null and ({support[n]}) then 1 else 0 end applied_{n}' for n in models)
 c.execute(f"""create or replace table s as select b.runner_id,b.race_id,b.race_date,b.venue,b.horse_no,b.field_size,b.ambiguous,b.n_hl60,f.distance_m,f.last_distance,f.last_same_venue,b.astar s_astar,b.a0 s_a0,b.astar_rank,b.a0_rank,{cols} from b join f using(runner_id) join g using(runner_id)""")
 assert c.execute('select count(*) from s').fetchone()==c.execute('select count(*) from b').fetchone()
 allmodels=['astar','a0']+models
 bad=' or '.join(f'(s_{n} is not null and not isfinite(s_{n}))' for n in allmodels)
 assert c.execute('select count(*) from s where '+bad).fetchone()[0]==0
 ranks=','.join(f'case when s_{n} is not null then row_number() over(partition by race_id order by round(s_{n},12) desc nulls last,horse_no asc) end r_{n}' for n in allmodels)
 p=B/f'pred_{mode}_{y}_t{th}.parquet'
 c.execute(f"copy (select *,{ranks},case when ambiguous then 'AMBIGUOUS_IDENTITY' when s_astar is null then 'INSUFFICIENT_HISTORY' else 'SCORED' end reason_astar from s order by runner_id) to '{p}' (format parquet,compression zstd)")
 assert c.execute(f"select count(*) from read_parquet('{p}') where r_astar is distinct from astar_rank or r_a0 is distinct from a0_rank").fetchone()[0]==0
 print(mode,y,th,sha(p),flush=True)

