"""Deterministic selection using predeclared development and validation rules."""
import json,csv,numpy as np,sys,hashlib
from pathlib import Path
B=Path(__file__).parent;mode=sys.argv[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def read(n):
 with open(B/n) as f:return list(csv.DictReader(f))
def selmetrics(mode):
 rr=read(f'metrics_{mode}.csv'); rows={}
 for r in rr:
  n=r.pop('model'); y=int(r['yr']);rows[n,y]={k:int(v or 0) for k,v in r.items()}
 return rows
def compare(rows,n,y,base='astar'):
 a,b=rows[n,y],rows[base,y];assert a['scored_races']==b['scored_races'] and a['scored_runners']==b['scored_runners']
 den=a['scored_races'];return {'wins_delta':a['wins']-b['wins'],'pp':100*(a['wins']-b['wins'])/den,'top3_delta_pp':100*(a['top3']-b['top3'])/den,'winner3_delta_pp':100*(a['winner3']-b['winner3'])/den,'applied':a['applied'],'den':den}
def pass_(r):return r['wins_delta']>0 and r['top3_delta_pp']>=-.5 and r['winner3_delta_pp']>=-.5
def ci(mode,n):
 rr=[r for r in read(f'blocks_{mode}.csv') if r['model']==n];rng=np.random.default_rng(20261124);nn=np.zeros(2000,dtype=np.int64);dd=np.zeros(2000,dtype=np.int64)
 for y in sorted(set(r['date'][:4] for r in rr)):
  q=[r for r in rr if r['date'].startswith(y)];n0=np.array([int(r['n']) for r in q]);d=np.array([int(r['delta']) for r in q]);idx=rng.integers(0,len(q),(2000,len(q)));nn+=n0[idx].sum(axis=1);dd+=d[idx].sum(axis=1)
 return [float(x) for x in np.quantile(100*dd/nn,[.025,.975])]
def save(n,d):(B/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
rows=selmetrics(mode);defs=json.loads((B/f'candidate_definitions_{mode}.json').read_text())
candidates=[]
for n in defs['models']:
 row=compare(rows,n,0);row.update(model=n,family=defs['family'][n],dev_eligible=pass_(row),ci95=ci(mode,n))
 if mode=='val':
  row['annual']=[compare(rows,n,y) for y in [2022,2023]];row['val_eligible']=pass_(row) and all(x['wins_delta']>0 for x in row['annual'])
 candidates.append(row)
if mode=='dev':
 selected=[]
 for f in ['B1','B2','B3','B4']:
  eligible=sorted((x for x in candidates if x['family']==f and x['dev_eligible']),key=lambda x:(-x['wins_delta'],x['model']))
  if eligible:selected.append(eligible[0]['model'])
 save('shortlist.json',{'status':'FROZEN_BEFORE_VALIDATION','models':selected,'development_metrics_sha256':sha(B/'metrics_dev.csv'),'config_sha256':sha(B/'run_config.json'),'decisions':candidates})
 print('shortlist',selected,flush=True)
elif mode=='val':
 shortlist=json.loads((B/'shortlist.json').read_text())['models'];good=[x for x in candidates if x['model'] in shortlist and x['val_eligible']]
 combo=next((x for x in candidates if x['model']=='combined'),None)
 # Combined is eligible only if all individual terms qualify, development combination itself positive,
 # and validation combo improves on best single without exceeding secondary guard.
 if combo:
  dv=selmetrics('combine_dev');dc=compare(dv,'combined',0)
  combo['development_combination']=dc
  combo['val_eligible']=combo['val_eligible'] and len(good)==len(shortlist) and pass_(dc)
  if good:
   best=max(good,key=lambda x:x['wins_delta'])['model']
   combo['incremental_vs_best']=compare(rows,'combined',0,best)
   combo['val_eligible']=combo['val_eligible'] and pass_(combo['incremental_vs_best'])
  if combo['val_eligible']:good.append(combo)
 selected=sorted(good,key=lambda x:(-x['wins_delta'],x['model']))[0]['model'] if good else 'astar'
 terms=shortlist if selected=='combined' else ([] if selected=='astar' else [selected])
 d={'status':'FROZEN_BEFORE_CONFIRMATION','id':'P8-Bstar-r1' if terms else 'P8-Astar-r1-fallback','selected':selected,'terms':terms,'base':'P8-Astar-r1','base_config_sha256':json.loads((B/'run_config.json').read_text())['base_config_sha256'],'validation_metrics_sha256':sha(B/'metrics_val.csv'),'shortlist_sha256':sha(B/'shortlist.json'),'run_config_sha256':sha(B/'run_config.json'),'definitions':{n:defs['expressions'][n] for n in terms},'decisions':candidates,'confirmation_opened':False,'production_approved':False}
 save('candidate_config.json',d);print('candidate',selected,terms,flush=True)
else:raise ValueError(mode)
